import path, { join } from 'path';
import rspack, { Configuration } from '@rspack/core';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const { ReactRefreshRspackPlugin: RefreshPlugin } = require('@rspack/plugin-react-refresh');
import { RspackManifestPlugin } from 'rspack-manifest-plugin';
import { PubsubMain } from '@teambit/pubsub';
import { Logger } from '@teambit/logger';
import NodePolyfillPlugin from 'node-polyfill-webpack-plugin';
import errorOverlayMiddleware from 'react-dev-utils/errorOverlayMiddleware';
import evalSourceMapMiddleware from 'react-dev-utils/evalSourceMapMiddleware';
import { WebpackBitReporterPlugin } from '@teambit/webpack';
import '@teambit/react.babel.bit-react-transformer';
import { mdxOptions } from '@teambit/mdx.modules.mdx-v3-options';
import { ComponentID } from '@teambit/component-id';
import { html } from './util/html';

process.env.NODE_ENV = 'development';

export const configFactory = (
  devServerID: string,
  workspaceDir: string,
  entryFiles: string[],
  publicRoot: string,
  publicPath: string,
  pubsub: PubsubMain,
  title?: string,
  favicon?: string
): Configuration => {
  const resolveWorkspacePath = (relativePath: string) =>
    path.resolve(workspaceDir, relativePath);

  const entry = entryFiles.map((filePath) => resolveWorkspacePath(filePath));
  const publicDirectory = `${publicRoot}${publicPath}`;

  const isDEV = process.env.NODE_ENV === 'development';
  const cloudWS = process.env._WORKSPACE_ID || undefined;

  const logger = new Logger('rspack-dev-server');

  return {
    experiments: {
      css: true,
    },
    lazyCompilation: {
      entries: false,
      imports: true,
    },
    devtool: 'eval-cheap-module-source-map',
    mode: 'development',
    entry,

    output: {
      // Development filename output
      path: resolveWorkspacePath(publicDirectory),
      // publicPath: resolveWorkspacePath(publicDirectory),
      filename: 'static/js/[name].bundle.js',
      chunkFilename: 'static/js/[name].chunk.js',
      cssFilename: 'static/css/[name].bundle.css',
      cssChunkFilename: 'static/css/[name].chunk.css',
      hashFunction: 'xxhash64',
      // point sourcemap entries to original disk locations (format as URL on windows)
      // devtoolModuleFilenameTemplate: (info) =>
      //   pathNormalizeToLinux(path.resolve(info.absoluteResourcePath)),
    },

    infrastructureLogging: {
      level: 'warn',
      console: {
        ...console,
        log: logger.console.bind(logger),
        info: logger.info.bind(logger),
        warn: logger.warn.bind(logger),
        error: logger.error.bind(logger),
        debug: logger.debug.bind(logger),
      },
    },

    devServer: {
      allowedHosts: ['localhost', '127.0.0.1', '.bit.cloud'],
      hot: true,
      liveReload: false,
      static: [
        {
          directory: resolveWorkspacePath(publicDirectory),
          staticOptions: {},
          // Don't be confused with `dev.publicPath`, it is `publicPath` for static directory
          // Can be:
          // publicPath: ['/static-public-path-one/', '/static-public-path-two/'],
          publicPath: publicDirectory,
          // Can be:
          // watch: {} (options for the `watch` option you can find https://github.com/paulmillr/chokidar)
          watch: {
            ignored: ['**/.git/**', '**/.bit/**'],
          },
        },
      ],

      compress: true,

      historyApiFallback: {
        disableDotRule: true,
        index: path.join('/', publicRoot, 'index.html'),
      },

      client: {
        logging: 'warn',
        overlay: {
          errors: true,
          warnings: false,
          runtimeErrors: true,
        },
        webSocketURL: {
          hostname: cloudWS
            ? `${cloudWS}p3000.workspaces.bit.cloud`
            : '0.0.0.0',
          port: cloudWS ? '443' : 3000,
          protocol: cloudWS ? 'https' : 'ws',
        },
      },

      setupMiddlewares: (middlewares, devServer) => {
        if (!devServer) {
          throw new Error('rspack-dev-server is not defined');
        }

        middlewares.push(
          // @ts-ignore - lets us fetch source contents from rspack for the error overlay
          evalSourceMapMiddleware(devServer),
          errorOverlayMiddleware()
        );
        return middlewares;
      },

      devMiddleware: {
        // forward static files
        publicPath: path.join('/', publicRoot),
      },

      watchFiles: {
        paths: [resolveWorkspacePath('**/*')],
        options: {
          ignored: [
            '**/.git/**',
            '**/.bit/**',
            '**/node_modules/!(.bit_roots)/**',
          ],
        },
      },
    },

    target: ['web', 'es5'],

    resolve: {
      extensions: ['.ts', '.tsx', '.jsx', '...'],
    },

    module: {
      generator: {
        'css/auto': {
          esModule: false,
          exportsConvention: 'camel-case-only',
          localIdentName: '[name]__[local]-[hash:base64:5]',
        },
        css: {
          esModule: false,
        },
        'css/module': {
          esModule: false,
          exportsConvention: 'camel-case-only',
          localIdentName: '[name]__[local]-[hash:base64:5]',
        },
      },
      parser: {
        // `dashedIdents: false` keeps CSS custom properties (`--token`) GLOBAL.
        // rspack's native CSS modules scope dashed idents by default, so a
        // `var(--button-bg)` reference inside a `.module.css`/`.module.scss`
        // gets rewritten to the locally-hashed `var(--button.module__…-<hash>)`,
        // which no longer matches the unscoped `--button-bg` a theme defines
        // globally — theme tokens stop resolving and components render unstyled.
        // The webpack/`css-loader` pipeline (react-env <= 6.0.14) never scoped
        // custom properties; this restores that behaviour. Class names are still
        // scoped via `customIdents`/`localIdentName`.
        'css/auto': {
          namedExports: false,
          dashedIdents: false,
        },
        css: {
          namedExports: false,
        },
        'css/module': {
          namedExports: false,
          dashedIdents: false,
        },
      },
      rules: [
        // JavaScript, TypeScript and JSX files - using builtin:swc-loader
        {
          test: /\.(js|jsx|ts|tsx)$/,
          exclude: /node_modules/,
          use: {
            loader: 'builtin:swc-loader',
            options: {
              jsc: {
                parser: {
                  syntax: 'typescript',
                  tsx: true,
                },
                transform: {
                  react: {
                    runtime: 'automatic',
                    development: true,
                    refresh: true,
                  },
                },
                target: 'es2015',
              },
            },
          },
          type: 'javascript/auto',
        },
        {
          test: /\.js$/,
          // limit loader to files in the current project,
          // to skip any files linked from other projects (like Bit itself)
          include: path.join(workspaceDir, 'node_modules'),
          // only apply to packages with componentId in their package.json (ie. bit components)
          descriptionData: { componentId: ComponentID.isValidObject },
          use: [
            {
              loader: require.resolve('babel-loader'),
              options: {
                cacheDirectory: true,
                inputSourceMap: false,
                sourceMaps: false,
                babelrc: false,
                configFile: false,
                plugins: [
                  require.resolve('react-refresh/babel'),
                  // for component highlighting in preview.
                  [
                    require.resolve('@teambit/react.babel.bit-react-transformer'),
                  ],
                ].filter(Boolean),
                // turn off all optimizations (only slow down for node_modules)
                compact: false,
                minified: false,
              },
            },
          ],
        },
        // MDX v3 support
        {
          test: /\.mdx?$/,
          exclude: [/node_modules/],
          use: [
            {
              loader: require.resolve('babel-loader'),
              options: {
                cacheDirectory: true,
                sourceType: 'unambiguous',
                babelrc: false,
                configFile: false,
                presets: [
                  require.resolve('@babel/preset-env'),
                  require.resolve('@babel/preset-react'),
                ],
              },
            },
            {
              loader: require.resolve('@mdx-js/loader'),
              options: mdxOptions,
            },
            {
              loader: require.resolve('@teambit/mdx.modules.mdx-pre-loader'),
            },
          ],
        },
        {
          test: /\.mdx?$/,
          // to skip any files linked from other projects (like Bit itself)
          include: join(workspaceDir, 'node_modules', '.bit_roots'),
          // only apply to packages with componentId in their package.json (ie. bit components)
          descriptionData: { _bit_local: (value) => !!value },
          use: [
            {
              loader: require.resolve('babel-loader'),
              options: {
                cacheDirectory: true,
                sourceType: 'unambiguous',
                babelrc: false,
                configFile: false,
                compact: false,
                minified: false,
                presets: [
                  require.resolve('@babel/preset-react'),
                  require.resolve('@babel/preset-env'),
                ],
                plugins: [require.resolve('react-refresh/babel')],
              },
            },
            {
              loader: require.resolve('@mdx-js/loader'),
              options: mdxOptions,
            },
            {
              loader: require.resolve('@teambit/mdx.modules.mdx-pre-loader'),
            },
          ],
        },
        {
          test: /\.mdx?$/,
          // to skip any files linked from other projects (like Bit itself)
          include: join(workspaceDir, 'node_modules'),
          exclude: join(workspaceDir, 'node_modules', '.bit_roots'),
          // only apply to packages with componentId in their package.json (ie. bit components)
          descriptionData: { componentId: (value) => !!value },
          use: [
            {
              loader: require.resolve('babel-loader'),
              options: {
                cacheDirectory: true,
                sourceType: 'unambiguous',
                babelrc: false,
                configFile: false,
                presets: [
                  require.resolve('@babel/preset-react'),
                  require.resolve('@babel/preset-env'),
                ],
                plugins: [],
              },
            },
            {
              loader: require.resolve('@mdx-js/loader'),
              options: mdxOptions,
            },
            {
              loader: require.resolve('@teambit/mdx.modules.mdx-pre-loader'),
            },
          ],
        },
        {
          test: /\.css$/i,
          type: 'css', // this is enabled by default for .css, so you don't need to specify it
        },
        {
          test: /\.module\.css$/i,
          type: 'css/module', // this is enabled by default for module.css,   so you don't need to specify it
        },
        {
          test: /\.(sass|scss)$/,
          use: [
            {
              loader: require.resolve('sass-loader'),
              options: {
                api: 'modern-compiler',
                implementation: require.resolve('sass-embedded'),
                sassOptions: {
                  quietDeps: true,
                  silenceDeprecations: ['import', 'global-builtin'],
                  // ignore only @teambit/* deprecations
                  logger: {
                    warn(text: string, { deprecation, span }: any) {
                      const file = String(span?.url || '');
                      const fromBit = /node_modules\/@teambit\//.test(file);
                      if (deprecation && fromBit) return; // swallow
                      console.warn(text);
                    },
                    debug() {},
                  },
                },
              },
            },
          ],
          type: 'css/auto',
        },
        {
          test: /\.(png|jpe?g|gif)$/i,
          type: 'asset/resource',
        },
        {
          test: /\.svg$/,
          type: 'asset',
        },
      ],
    },

    optimization: {
      splitChunks: false,
    },

    stats: {
      preset: 'minimal',
    },

    watchOptions: {
      ignored: ['**/.git/**', '**/.bit/**', '**/node_modules/!(.bit_roots)/**'],
      followSymlinks: true,
    },

    plugins: [
      new rspack.HtmlRspackPlugin({
        templateContent: html(title || 'Bit Preview'),
        filename: 'index.html',
        favicon,
      }),
      isDEV && new rspack.HotModuleReplacementPlugin(),
      isDEV && new RefreshPlugin(),
      new rspack.DefinePlugin({
        'process.env.NODE_ENV': JSON.stringify('development'),
      }),
      new RspackManifestPlugin({
        fileName: 'assets-manifest.json',
        assetHookStage: 5000,
        map: (f) => {
          // eslint-disable-next-line no-param-reassign
          f.path = f.path.replace(/^auto\//, '');
          return f;
        },
      }),
      new NodePolyfillPlugin(),
      new WebpackBitReporterPlugin({
        options: { pubsub, devServerID },
      }),
    ].filter(Boolean),
  };
};
